-- Expand Software Developer and UX/UI Design Beginner curricula to match
-- the rich module structures in frontend/src/data/courses.ts.
-- Replaces thin V17 groupings (2 lessons each) with 6 lessons and many
-- sub-lessons; rebuilds course_lessons / sub_lessons (progress cascades).

DELETE FROM courseflow.demo_lesson_content
WHERE course_title IN ('Software Developer', 'UX/UI Design Beginner');

INSERT INTO courseflow.demo_lesson_content (
    course_title, lesson_name, sub_lesson_name, lesson_order, sub_lesson_order,
    title, objective, paragraph_one, paragraph_two, paragraph_three, paragraph_four,
    example, exercise, solution
) VALUES
('Software Developer', 'Getting Started as a Developer', 'Welcome to Software Development', 1, 1, 'Welcome to Software Development', 'Set expectations for practice and progress as a beginner developer.', 'Software development is learned by writing small programs, reading errors, and improving one piece at a time. Speed matters less than a habit of finishing a tiny, working result.', 'Plan short practice sessions. After each lesson, rewrite the idea in your own words and try one example without looking at the answer first.', 'Practice Welcome to Software Development in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write one practice habit you will keep for the next seven days. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Welcome to Software Development, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A first week goal can be: open the editor, run a one-line print, and save a short note about what failed.', 'Write one practice habit you will keep for the next seven days.', 'Example: 30 minutes daily, one small program, and a note of the error you fixed. Adjust the time if needed, but keep the finish-a-result rule.'),
('Software Developer', 'Getting Started as a Developer', 'How Software Projects Are Built', 1, 2, 'How Software Projects Are Built', 'Describe the path from idea to a shipped product.', 'Most projects move through requirements, design, coding, testing, and deployment. Teams may rename the stages, but someone still has to decide what to build, build it, check it, and put it where users can reach it.', 'Write the user outcome first. Then list what must be true before coding, what you will check after coding, and who will try the result.', 'Practice How Software Projects Are Built in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: List the five stages for a tiny to-do app and one check for each stage. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study How Software Projects Are Built, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A course list page needs content structure before styling, and a way to open one lesson before you polish every button.', 'List the five stages for a tiny to-do app and one check for each stage.', 'Requirements: add and complete a task. Design: sketch the list. Code: save items. Test: empty name rejected. Deploy: a URL someone else can open.'),
('Software Developer', 'Getting Started as a Developer', 'Choosing Your First Language', 1, 3, 'Choosing Your First Language', 'Explain why beginners often start with JavaScript for the web.', 'A first language should let you see results quickly and practice core ideas: variables, conditions, loops, and functions. JavaScript runs in the browser and on Node.js, so one language covers many beginner projects.', 'Compare options by practice speed and community help, not by what sounds advanced. You can learn another language later with the same problem-solving habits.', 'Practice Choosing Your First Language in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Name two reasons to start with JavaScript and one reason you might choose another language later. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Choosing Your First Language, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Printing a message in the browser console or with Node.js both teach input, process, and output without a heavy setup.', 'Name two reasons to start with JavaScript and one reason you might choose another language later.', 'Quick feedback in the browser, and reuse of web APIs. Later you might choose Python for data work or another language for a specific job.'),
('Software Developer', 'Getting Started as a Developer', 'Setting Up Your Dev Environment', 1, 4, 'Setting Up Your Dev Environment', 'Install an editor, a runtime, and a terminal workflow you can repeat.', 'An editor is where you write files. A terminal runs commands. A runtime such as Node.js executes JavaScript outside the browser. Version control records history so you can inspect and undo changes.', 'Create a project folder and a README that says how to start. Install only what you need for the next lesson, then verify each tool with one command.', 'Practice Setting Up Your Dev Environment in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: List the tools you installed and what each one is used for. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Setting Up Your Dev Environment, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'After installing Node.js, run node -v and print a Hello message from a file to confirm the path works.', 'List the tools you installed and what each one is used for.', 'VS Code for editing, Node.js to run JavaScript, a terminal to run commands, and Git for version history. Confirm each with a version or hello command.'),
('Software Developer', 'Getting Started as a Developer', 'Your First Program', 1, 5, 'Your First Program', 'Write, save, and run a tiny console program.', 'A first program teaches the loop of edit, save, run, and read the output. Keep the task tiny so you can focus on the tools rather than a large design.', 'Write the steps in plain language, type them into a file, run the file, and change one value to see the output change.', 'Practice Your First Program in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write the steps to print the average of 60, 75, and 90, then run them. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Your First Program, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'console.log(2 + 3) prints 5. Changing 3 to 4 should print 6. If nothing prints, check the file path and the command you ran.', 'Write the steps to print the average of 60, 75, and 90, then run them.', 'Add the three numbers to 225, divide by 3, and print 75. If a value is not a number, fix the input before calculating.'),
('Software Developer', 'Getting Started as a Developer', 'Git Basics for Beginners', 1, 6, 'Git Basics for Beginners', 'Use init, status, add, and commit to track safe snapshots.', 'Git records versions of your files. Status shows what changed. Add stages chosen files. Commit saves a snapshot with a message. Push shares commits with a remote when you have one.', 'Make small commits that share one purpose. Never put passwords into history. Read the status before and after each step until the flow feels routine.', 'Practice Git Basics for Beginners in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Explain the difference between git add and git commit in your own words. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Git Basics for Beginners, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'After editing a price formula, stage only that file and commit with a message that says what the change does.', 'Explain the difference between git add and git commit in your own words.', 'Add chooses which changes belong in the next snapshot. Commit records those staged changes with a message. Unstaged edits stay out of that snapshot.'),
('Software Developer', 'Getting Started as a Developer', 'Reading Error Messages', 1, 7, 'Reading Error Messages', 'Use an error message as a clue instead of a blocker.', 'An error usually names a file, a line, and a reason. Read from the top: what failed, where it failed, and what the program expected. Panic makes you change too many things at once.', 'Reproduce the error with the smallest input. Change one thing, run again, and note what changed. Search the exact message only after you can describe the failing step.', 'Practice Reading Error Messages in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Rewrite a scary error into: file, line, expected vs actual, and your next try. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Reading Error Messages, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'ReferenceError: count is not defined means you used count before creating it, or mistyped the name.', 'Rewrite a scary error into: file, line, expected vs actual, and your next try.', 'Example: app.js line 12 expected a number named score but score was undefined. Next try: declare score before using it and re-run.'),
('Software Developer', 'Getting Started as a Developer', 'Asking Good Questions When Stuck', 1, 8, 'Asking Good Questions When Stuck', 'Write a clear problem statement with expected versus actual behavior.', 'A good question helps someone help you. Include what you tried, the expected result, the actual result, and a minimal example. Vague questions force others to guess your setup.', 'Reduce the code to the smallest case that still fails. State the environment briefly. Ask one question at a time.', 'Practice Asking Good Questions When Stuck in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Draft a help request for a loop that never stops. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Asking Good Questions When Stuck, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Instead of ''''my form is broken'''', write: submitting an empty email should show Required, but nothing appears. Here is the validation function.', 'Draft a help request for a loop that never stops.', 'Expected: stop after three items. Actual: runs forever. Include the loop condition, the sample list, and what you already tried to change.'),
('Software Developer', 'Programming Fundamentals', 'Variables and Data Types', 2, 1, 'Variables and Data Types', 'Choose a data type that matches the meaning of the value.', 'A variable is a name for a value. Basic types include numbers, text, and true or false. A number you will calculate is different from text that only looks numeric, such as a student id that can start with zero.', 'Name variables for what they mean, check the type you received, and convert on purpose. In JavaScript, adding text and a number can concatenate instead of calculate.', 'Practice Variables and Data Types in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Choose types for the code ''0012'', the price 99.5, and a paid status, and say why. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Variables and Data Types, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'const price = 40 and const quantity = 3 give total = price * quantity, which is 120. The expression ''40'' + 3 produces the text ''403''.', 'Choose types for the code ''0012'', the price 99.5, and a paid status, and say why.', 'The code is a string so the leading zeros stay. The price is a number so you can calculate. The paid status is a boolean such as true, not the text ''true'', if you will test it as a boolean.'),
('Software Developer', 'Programming Fundamentals', 'Operators and Expressions', 2, 2, 'Operators and Expressions', 'Combine values with arithmetic, comparison, and logical operators.', 'Operators build expressions: arithmetic changes numbers, comparison yields true or false, and logical operators combine conditions. Parentheses control order when the default order is unclear.', 'Write the expression in words first, then in code. Check boundary values, especially equality and off-by-one mistakes.', 'Practice Operators and Expressions in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write expressions for: at least 3 items, and either a member or a coupon. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Operators and Expressions, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'score >= 50 is true for 50. score > 50 is false for 50. Mixing && and || without parentheses is a common source of bugs.', 'Write expressions for: at least 3 items, and either a member or a coupon.', 'items >= 3 && (isMember || hasCoupon). Test 2 items with a coupon, 3 items without either, and 3 items with membership.'),
('Software Developer', 'Programming Fundamentals', 'Conditionals and Control Flow', 2, 3, 'Conditionals and Control Flow', 'Use if/else patterns so programs react to different inputs.', 'A condition chooses which instructions run. Cover the cases that matter, including boundaries and invalid input. Unhandled cases often fail silently.', 'Write the rule in words, then implement it. Test below, equal to, and above each boundary. Prefer clear branches over clever nesting.', 'Practice Conditionals and Control Flow in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a short decision tree for a login form: success, wrong password, missing email. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Conditionals and Control Flow, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'if (score >= 50) treats 50 as a pass. An else branch should say what happens when the score is below 50.', 'Write a short decision tree for a login form: success, wrong password, missing email.', 'If email empty → show required. Else if password wrong → show error. Else → redirect home. Test each branch once.'),
('Software Developer', 'Programming Fundamentals', 'Loops and Iteration', 2, 4, 'Loops and Iteration', 'Process lists with for and while without repeating code by hand.', 'A loop repeats instructions across many items. Every loop needs a clear stop condition. Off-by-one errors and infinite loops usually come from the start value, the end check, or the update step.', 'Try an empty list and a list with several items. Prefer looping over a collection when you already have the items.', 'Practice Loops and Iteration in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a loop plan that sums prices and stops early if any price is invalid. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Loops and Iteration, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Looping over [40, 50, 80] can count how many scores are at least 50.', 'Write a loop plan that sums prices and stops early if any price is invalid.', 'Start total at 0. For each price, if it is not a number or is negative, stop and report an error. Otherwise add it. Test [] and [10, -1].'),
('Software Developer', 'Programming Fundamentals', 'Functions and Parameters', 2, 5, 'Functions and Parameters', 'Split work into a function with a clear input and output.', 'A function groups the steps of one job. It takes parameters and returns a value. Splitting lets you change one rule in one place and test it with sample inputs.', 'Separate calculation from display. State the input and the output. A function that does not change outside data is easier to test.', 'Practice Functions and Parameters in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Sketch a function that averages a list of numbers, including the result for an empty list. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Functions and Parameters, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'function total(price, quantity) { return price * quantity } calculates without depending on a button. total(40, 3) is 120.', 'Sketch a function that averages a list of numbers, including the result for an empty list.', 'Add the values and divide by the count. An empty list can return null, and the caller must handle that. Test [2, 4] to 3, [5] to 5, and [] to null.'),
('Software Developer', 'Programming Fundamentals', 'Arrays and Objects', 2, 6, 'Arrays and Objects', 'Model real data with arrays and objects, then update nested values safely.', 'Arrays store ordered lists. Objects store named fields. Most app data is a mix: a list of course objects, each with a title and a price.', 'Choose names that match the grain of one item. When you update nested data, copy carefully so you do not change another item by accident.', 'Practice Arrays and Objects in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Design an object for one lesson progress row and an array of three such rows. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Arrays and Objects, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'const course = { title: ''UX'', price: 199 }; courses.push(course) adds one item to a list.', 'Design an object for one lesson progress row and an array of three such rows.', 'Each row can have lessonId, status, and updatedAt. The array holds three rows. Updating row two must not change row one.'),
('Software Developer', 'Building for the Web', 'HTML Structure Essentials', 3, 1, 'HTML Structure Essentials', 'Create semantic page structure with headings, sections, and forms.', 'HTML describes the meaning of content: headings, paragraphs, lists, links, and form controls. Semantic tags help people and assistive tools understand the page.', 'Build the outline before styling. Every input needs a label. Use one h1 for the page topic and nest headings in order.', 'Practice HTML Structure Essentials in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Outline the HTML for a signup form with email, password, and submit. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study HTML Structure Essentials, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A course detail page can use h1 for the course name, a section for the syllabus, and a form for enrollment.', 'Outline the HTML for a signup form with email, password, and submit.', 'A form with labeled email and password inputs, a submit button, and a place for an error message. Do not rely on placeholder text alone as the label.'),
('Software Developer', 'Building for the Web', 'CSS Layout Basics', 3, 2, 'CSS Layout Basics', 'Use flexbox and spacing to build clean layouts.', 'CSS controls layout, spacing, and visual hierarchy. Flexbox aligns items in a row or column. Consistent spacing is easier to maintain than one-off pixel guesses.', 'Start with structure, then spacing, then decoration. Check the layout at a narrow width early so you do not paint yourself into a corner.', 'Practice CSS Layout Basics in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Describe a flex layout for a header with a logo on the left and links on the right. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study CSS Layout Basics, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A course card row can use display: flex with a gap so cards share space without overlapping.', 'Describe a flex layout for a header with a logo on the left and links on the right.', 'A flex container with space-between, logo as the first child, and a nav group as the second. Add a gap inside the nav links.'),
('Software Developer', 'Building for the Web', 'DOM Manipulation', 3, 3, 'DOM Manipulation', 'Select elements, update text, and respond to clicks in the browser.', 'The DOM is the live tree of page elements. JavaScript can find nodes, change text and attributes, and listen for events such as clicks.', 'Keep a clear source of truth for the data, then update the DOM from that data. Avoid scattering the same value in many places.', 'Practice DOM Manipulation in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write the steps to toggle a wishlist button label between Save and Saved. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study DOM Manipulation, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'document.querySelector(''#status'').textContent = ''Saved'' updates a status line after a successful action.', 'Write the steps to toggle a wishlist button label between Save and Saved.', 'Find the button, read the current state, flip the state, set the label, and keep aria attributes in sync with the visible text.'),
('Software Developer', 'Building for the Web', 'Working with APIs and JSON', 3, 4, 'Working with APIs and JSON', 'Fetch data from an API, parse JSON, and render the result.', 'An API returns data your page did not hard-code. JSON is a common text format for objects and arrays. Fetching is a network step that can succeed or fail.', 'Handle loading and error states. Check the response status before parsing. Render only the fields you need.', 'Practice Working with APIs and JSON in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Describe one API response field you would display on a course card and why. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Working with APIs and JSON, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A course list API might return [{ id: 1, title: ''UX'' }]. Showing title on a card is enough for a first render.', 'Describe one API response field you would display on a course card and why.', 'Title identifies the course for the learner. Price supports the buy decision. Prefer fields the user can verify on the detail page.'),
('Software Developer', 'Building for the Web', 'Async Code with Promises', 3, 5, 'Async Code with Promises', 'Handle loading and failed requests with promises or async/await.', 'Async work finishes later. Promises and async/await help you wait for a result without blocking the whole page. Always plan for failure and for the waiting state.', 'Show loading while the request runs. On failure, show a message and a retry path. Do not leave the UI looking successful when the request failed.', 'Practice Async Code with Promises in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write the UI states for loading a lesson reading. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Async Code with Promises, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'await fetch(url) can throw or return a non-OK status. Catch both and tell the user what to do next.', 'Write the UI states for loading a lesson reading.', 'Idle, loading, success with content, and error with retry. Never show the previous lesson as if it were the new one while loading.'),
('Software Developer', 'Application Structure', 'Splitting Code into Modules', 4, 1, 'Splitting Code into Modules', 'Organize a project into folders and modules that stay easy to change.', 'Modules group related code behind a small public surface. Clear folders help you find features without reading every file.', 'Separate UI rendering from data fetching and from pure calculations when you can. Export only what other files need.', 'Practice Splitting Code into Modules in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Propose three modules for a tiny course catalog page. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Splitting Code into Modules, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A prices.js module can export total(price, quantity) while a page file imports it and displays the result.', 'Propose three modules for a tiny course catalog page.', 'api.js for fetching courses, courseCard.js for rendering one card, and main.js to load data and mount the list.'),
('Software Developer', 'Application Structure', 'State and Side Effects', 4, 2, 'State and Side Effects', 'Separate stored data from UI updates and avoid buggy double-writes.', 'State is the data your UI reflects. A side effect reaches outside that data, such as writing to the network or local storage. Mixing them carelessly causes double updates and stale screens.', 'Decide what the single source of truth is. Update state first, then let the UI follow. Trigger side effects on purpose, with a clear success and failure path.', 'Practice State and Side Effects in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Name the state and the side effect for marking a lesson complete. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study State and Side Effects, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Saving a completed lesson should update local state only after the server confirms, or roll back if the save fails.', 'Name the state and the side effect for marking a lesson complete.', 'State: lesson status. Side effect: POST to the server. On failure, keep the previous status and show an error.'),
('Software Developer', 'Application Structure', 'Forms and Validation', 4, 3, 'Forms and Validation', 'Build a form with client-side validation and clear error messages.', 'Forms collect input. Validation checks rules before or after submit. Messages should say what is wrong and how to fix it, next to the field when possible.', 'Validate required fields, formats, and matching values. Disable or protect double submit. Keep server validation even when the client already checks.', 'Practice Forms and Validation in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: List three validation rules you would add to a sign-up form. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Forms and Validation, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'An empty email should show Required under the field, not only a red border.', 'List three validation rules you would add to a sign-up form.', 'Email required and looks like an email, password at least a stated length, and confirm password matches. Show field-level messages.'),
('Software Developer', 'Application Structure', 'Debugging Strategies', 4, 4, 'Debugging Strategies', 'Isolate bugs with logging, breakpoints, and reproduction steps.', 'Debugging is a search: reproduce, narrow, fix, and confirm. Changing many things at once hides the cause.', 'Write the expected versus actual result. Reduce the input. Use a breakpoint or a log at the decision point. Confirm with a regression case after the fix.', 'Practice Debugging Strategies in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write reproduction steps for a bug where completing task A also completes task B. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Debugging Strategies, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'If a total is 403 instead of 120, log the types of price and quantity before the multiplication.', 'Write reproduction steps for a bug where completing task A also completes task B.', 'Start with two tasks, complete A, observe B. Note ids in state. Hypothesis: shared object reference. Fix and retest both tasks.'),
('Software Developer', 'Quality and Collaboration', 'Writing Readable Code', 5, 1, 'Writing Readable Code', 'Apply naming, small functions, and comments that explain why.', 'Readable code helps the next reader, including future you. Names should say what a value means. Functions should do one job. Comments explain non-obvious reasons, not every line.', 'Prefer clear code over clever code. Delete dead experiments before you share a change.', 'Practice Writing Readable Code in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Rewrite a vague name and add one why-comment for a magic number. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Writing Readable Code, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'isEligibleForDiscount is clearer than flag. A comment can explain why a discount starts at 1000 if that number comes from a business rule.', 'Rewrite a vague name and add one why-comment for a magic number.', 'Rename n to itemCount. Comment: // 1000 is the marketing threshold agreed for Q1, not a technical limit.'),
('Software Developer', 'Quality and Collaboration', 'Intro to Automated Tests', 5, 2, 'Intro to Automated Tests', 'Write a first unit test that protects a future change.', 'A unit test checks a small piece of behavior with a known input and expected output. Tests catch regressions when you change code later.', 'Start with pure functions. Name the case you are protecting. Run the test after every change to that function.', 'Practice Intro to Automated Tests in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write one test case for averaging [2, 4] and one for an empty list. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Intro to Automated Tests, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'expect(total(40, 3)).toBe(120) protects the multiplication rule.', 'Write one test case for averaging [2, 4] and one for an empty list.', 'Average of [2, 4] is 3. Empty list returns null or throws by the rule you chose. Assert the chosen rule explicitly.'),
('Software Developer', 'Quality and Collaboration', 'Code Reviews and Pull Requests', 5, 3, 'Code Reviews and Pull Requests', 'Open a PR, give constructive feedback, and respond to review comments.', 'A pull request shares a change for review before it merges. Good descriptions explain the why, the test plan, and any risk. Feedback should be specific and kind.', 'Keep PRs small enough to review. Reply to comments with what you changed or why you disagree. Do not take style notes as personal criticism.', 'Practice Code Reviews and Pull Requests in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a short PR description for a feature that adds a search bar. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Code Reviews and Pull Requests, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A PR that adds search can list: motivation, screenshots, and how you tested empty and matching queries.', 'Write a short PR description for a feature that adds a search bar.', 'Why: learners need to find courses by name. What: search input filters the list. Test: empty query shows all, unknown query shows empty state.'),
('Software Developer', 'Quality and Collaboration', 'Deploying a Simple App', 5, 4, 'Deploying a Simple App', 'Publish a static frontend and verify the live URL.', 'Deployment puts your app where others can open it. A static frontend needs built files hosted on a service, plus a check that the live URL loads.', 'Confirm environment settings, open the live site in a private window, and walk the main path. Note what still points to localhost.', 'Practice Deploying a Simple App in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a four-step release checklist for a static course catalog. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Deploying a Simple App, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'After deploy, open the course list URL and confirm cards load without console errors that block the page.', 'Write a four-step release checklist for a static course catalog.', 'Build succeeds, live URL opens, main list renders, and a broken API shows a clear error instead of a blank page.'),
('Software Developer', 'Course Summary', 'Key Takeaways for Junior Developers', 6, 1, 'Key Takeaways for Junior Developers', 'Recap the core skills from fundamentals through shipping a small app.', 'You practiced problem breakdown, language basics, web building blocks, structure, tests, and collaboration. The through-line is finishing a small path and checking it.', 'Keep a personal checklist: can you explain input-process-output, read an error, fetch JSON, and describe done for a tiny feature?', 'Practice Key Takeaways for Junior Developers in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: List five skills from this course you can demonstrate with evidence. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Key Takeaways for Junior Developers, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A junior portfolio piece can be a to-do app with validation, tests for total(), and a short README.', 'List five skills from this course you can demonstrate with evidence.', 'Variables and functions, DOM updates, API fetch with error handling, a unit test, and a PR or deploy note. Attach a link or screenshot for each.'),
('Software Developer', 'Course Summary', 'Building Your Learning Portfolio', 6, 2, 'Building Your Learning Portfolio', 'Turn course projects into a portfolio that shows growth.', 'Employers look for proof you can finish and explain work. A portfolio case study shows the problem, your approach, what you built, and what you learned.', 'Pick projects with a clear user outcome. Show a screenshot, a short write-up, and a link if possible. Note tradeoffs and bugs you fixed.', 'Practice Building Your Learning Portfolio in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Outline three portfolio projects you want to build next and why. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Building Your Learning Portfolio, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Instead of ''''I know JavaScript'''', show a deployed list page that loads courses from an API and handles failure.', 'Outline three portfolio projects you want to build next and why.', 'Example: course catalog with search, a progress tracker with local state, and a small API-backed form. Each should teach one new skill you can name.'),
('UX/UI Design Beginner', 'Design Foundations', 'Welcome to UX/UI Design', 1, 1, 'Welcome to UX/UI Design', 'Set course goals, weekly rhythm, and how critique helps you improve.', 'UX/UI design is learned by shipping small artifacts, then improving them with feedback. Critique is a tool for clarity, not a grade on your worth.', 'Expect a rhythm of learn, make, share, and revise. Keep versions so you can show how a screen changed after feedback.', 'Practice Welcome to UX/UI Design in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write your goal for this course in one sentence and how you will practice weekly. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Welcome to UX/UI Design, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A first week goal can be: one research note, one wireframe, and one written question for critique.', 'Write your goal for this course in one sentence and how you will practice weekly.', 'Example: design a clearer signup path. Practice: two focused hours, one critique request, and a short reflection each week.'),
('UX/UI Design Beginner', 'Design Foundations', 'What Designers Actually Do', 1, 2, 'What Designers Actually Do', 'Map day-to-day designer work across research, flows, visuals, and handoff.', 'Designers investigate problems, structure flows, shape interfaces, prototype interactions, and prepare work for engineering. Titles vary, but the work still connects user need to a usable product.', 'On a real team, you will spend time clarifying the problem as much as drawing screens. Document decisions so others can follow them.', 'Practice What Designers Actually Do in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: List five activities a beginner designer should practice, not only final visuals. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study What Designers Actually Do, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A designer might interview three users, redraw a checkout flow, and list edge cases before polishing colors.', 'List five activities a beginner designer should practice, not only final visuals.', 'Talk to a user, map a journey, wireframe a path, define empty and error states, and write handoff notes for one component.'),
('UX/UI Design Beginner', 'Design Foundations', 'UX vs UI vs Product Design', 1, 3, 'UX vs UI vs Product Design', 'Clarify role boundaries and how overlapping titles still collaborate.', 'UX focuses on the experience of reaching a goal. UI focuses on the interface someone sees and uses. Product design often spans both plus business constraints. Teams collaborate when titles overlap.', 'Name the one job of a screen, then order heading, text, and action by importance. A polished UI does not guarantee a clear UX.', 'Practice UX vs UI vs Product Design in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Order four pieces of information on a course signup screen and say why. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study UX vs UI vs Product Design, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A payment screen should show the total, the items, and a clear confirm button. An error needs words, not only a red border.', 'Order four pieces of information on a course signup screen and say why.', 'Course name and outcome confirm the page. Price and terms support the decision. Detail comes next. The signup button belongs where the cost is already visible.'),
('UX/UI Design Beginner', 'Design Foundations', 'Design Thinking in Practice', 1, 4, 'Design Thinking in Practice', 'Walk empathize, define, ideate, prototype, and test with a small example.', 'Design thinking is a way to learn about problems and test responses. It is not a single pass you finish and file. When an assumption is wrong, return to what you observed.', 'Separate evidence from guesses. Test the riskiest assumption with the smallest prototype that can answer it.', 'Practice Design Thinking in Practice in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Pick one everyday app and describe a pain point you would redesign first. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Design Thinking in Practice, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'People may skip a library because hours clash with work. A booking app does not help if the constraint is opening time.', 'Pick one everyday app and describe a pain point you would redesign first.', 'A food delivery checkout with too many steps before payment: simplify address and tip selection, then test whether people finish faster.'),
('UX/UI Design Beginner', 'Design Foundations', 'Choosing Design Tools', 1, 5, 'Choosing Design Tools', 'Set up Figma files, pages, and components for class projects.', 'Tools help you explore and share designs. Figma is common for interface work because files, components, and prototypes live together. The tool matters less than clear structure.', 'Create pages for research, wireframes, UI, and prototype. Name frames by task. Start a small component set early so screens stay consistent.', 'Practice Choosing Design Tools in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Describe how you will organize one Figma file for this course. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Choosing Design Tools, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A Beginner Project file can have pages named Research, Flows, UI Kit, and Prototype.', 'Describe how you will organize one Figma file for this course.', 'Pages for research notes, wireflows, high-fidelity screens, and prototype links. Components for button, input, and course card.'),
('UX/UI Design Beginner', 'Design Foundations', 'Accessibility Mindset from Day One', 1, 6, 'Accessibility Mindset from Day One', 'Treat contrast, focus, and labels as core skills, not polish.', 'Inclusive design helps more people complete tasks. Contrast, focus states, labels, and keyboard paths are part of the interface, not optional decoration.', 'Check text on the real background. Pair color with text or an icon for status. Ensure every control has a name a screen reader can announce.', 'Practice Accessibility Mindset from Day One in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: List three accessibility checks you will apply to every screen you design. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Accessibility Mindset from Day One, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A completed state needs both an icon and the words Completed, not color alone.', 'List three accessibility checks you will apply to every screen you design.', 'Contrast of text and controls, visible focus order, and labels on inputs. Add a fourth if you can: tap target size on mobile.'),
('UX/UI Design Beginner', 'Design Foundations', 'Collecting Inspiration Without Copying', 1, 7, 'Collecting Inspiration Without Copying', 'Build a mood board and extract patterns ethically from references.', 'Inspiration helps you see patterns in layout, hierarchy, and tone. Copying a whole product is not learning. Extract principles: spacing rhythm, type scale, or how empty states explain next steps.', 'Save references with a note about why they work. Rebuild the idea in your own content and constraints.', 'Practice Collecting Inspiration Without Copying in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Collect three references and write one reusable pattern from each. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Collecting Inspiration Without Copying, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A calm settings page may inspire your spacing system without taking its icons or brand colors.', 'Collect three references and write one reusable pattern from each.', 'Example: clear primary action placement, generous section spacing, and an empty state with one next step. Apply them to your own course app screens.'),
('UX/UI Design Beginner', 'Design Foundations', 'Giving and Receiving Critique', 1, 8, 'Giving and Receiving Critique', 'Practice feedback that is specific, kind, and actionable.', 'Useful critique names the goal, what you observed, and a suggestion to try. Vague praise or vague dislike does not help someone revise.', 'When you receive critique, restate it, ask a clarifying question, and choose one change to test. Separate taste from task success.', 'Practice Giving and Receiving Critique in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Rewrite a vague comment into actionable critique for a course list screen. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Giving and Receiving Critique, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Instead of ''''I do not like this'''', say ''''new users may miss Start because it sits below a long description''''.', 'Rewrite a vague comment into actionable critique for a course list screen.', 'Observation: the price competes with the course title. Suggestion: make the title the strongest text and group price with the enroll action.'),
('UX/UI Design Beginner', 'Understanding Users', 'User Research Methods', 2, 1, 'User Research Methods', 'Choose interviews, surveys, or usability sessions for the question at hand.', 'User research checks assumptions about a problem. Different methods fit different questions: interviews for reasons, surveys for patterns at scale, usability tests for whether a task works.', 'Ask about a real recent event. Keep participant words separate from your interpretation.', 'Practice User Research Methods in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write three interview questions for someone who has bought an online course. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study User Research Methods, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Instead of ''''would you like a new learning app?'''', ask how they chose a course last time and where they stopped.', 'Write three interview questions for someone who has bought an online course.', 'Where did you start the last search; what did you compare; was there a moment you nearly did not buy. Do not suggest the cause for them.'),
('UX/UI Design Beginner', 'Understanding Users', 'Personas and Jobs to Be Done', 2, 2, 'Personas and Jobs to Be Done', 'Turn research notes into personas and job statements that guide decisions.', 'A persona summarizes a relevant user pattern. A job-to-be-done statement names the progress someone wants in a situation. Both should point back to evidence.', 'Avoid fictional hobbies that do not change the design. Focus on goals, constraints, and triggers.', 'Practice Personas and Jobs to Be Done in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write one persona bullet and one job statement from notes about confused beginners. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Personas and Jobs to Be Done, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'When I am choosing a first design course, I want a clear beginner path so I do not waste money on advanced material.', 'Write one persona bullet and one job statement from notes about confused beginners.', 'Persona: first-time learner with limited evening time. Job: help me see which lesson to start so I can finish one session tonight.'),
('UX/UI Design Beginner', 'Understanding Users', 'User Journey Mapping', 2, 3, 'User Journey Mapping', 'Plot emotions, actions, and pain points across an end-to-end experience.', 'A journey map shows steps, actions, feelings, and problems for one user in one situation. Useful maps cite observation or a real story.', 'Ask about the last time they used the service, split the story into stages, and keep quotes separate from assumptions.', 'Practice User Journey Mapping in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Map one journey step that frustrates users and propose a design opportunity. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study User Journey Mapping, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A course applicant searches, compares, pays, and waits for email. The stuck point may be not knowing whether payment succeeded.', 'Map one journey step that frustrates users and propose a design opportunity.', 'Finding cancel after checkout is hard; opportunity: place account actions in a clearer settings menu, then test with a cancel task.'),
('UX/UI Design Beginner', 'Understanding Users', 'Synthesizing Insights', 2, 4, 'Synthesizing Insights', 'Cluster findings into themes and write problem statements teams can act on.', 'Synthesis turns scattered notes into patterns. A theme should describe what the evidence shares, not a vague bucket such as user problems.', 'Group observations by meaning, name the theme, keep links to evidence, and preserve cases that do not fit.', 'Practice Synthesizing Insights in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Build a theme from notes about missing Start, unknown lesson order, and unknown prerequisites. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Synthesizing Insights, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'I do not know if I paid and I am still waiting for the email may share a theme about missing confirmation after payment.', 'Build a theme from notes about missing Start, unknown lesson order, and unknown prerequisites.', 'Theme: the starting path is not visible. Keep evidence about the button, order, and prerequisites separate so you do not force one fix.'),
('UX/UI Design Beginner', 'Information Architecture and Flows', 'Sitemaps and Content Inventory', 3, 1, 'Sitemaps and Content Inventory', 'Organize product content so users can find what they need.', 'Information architecture is how content is grouped and labeled. A sitemap shows hierarchy. A content inventory lists what exists so you do not design from memory.', 'Group by user goals, not by org chart. Use labels people recognize from research.', 'Practice Sitemaps and Content Inventory in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Draft a mini sitemap for a beginner course platform with four top-level areas. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Sitemaps and Content Inventory, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A learning product might group Catalog, My Courses, and Account rather than mixing billing into every lesson page.', 'Draft a mini sitemap for a beginner course platform with four top-level areas.', 'Home/Catalog, Course player, Progress, and Account/Help. Note which pages a new learner needs first.'),
('UX/UI Design Beginner', 'Information Architecture and Flows', 'User Flows', 3, 2, 'User Flows', 'Draw the path a user takes to complete a key task before designing screens.', 'A user flow shows decisions and screens on the way to a goal. Drawing the path first prevents decorating screens that do not connect.', 'Start from entry and success. Add branches for errors and exits. Keep the happy path short enough to test.', 'Practice User Flows in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Sketch a flow for saving a course to a wishlist, including already-saved. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study User Flows, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Choose course → view detail → enroll → open lesson one is a flow you can prototype before visual UI.', 'Sketch a flow for saving a course to a wishlist, including already-saved.', 'Not saved → tap save → saved. If already saved, tap removes it. Include a way to open the saved list.'),
('UX/UI Design Beginner', 'Information Architecture and Flows', 'Wireframing Low-Fidelity Screens', 3, 3, 'Wireframing Low-Fidelity Screens', 'Sketch structure first so layout decisions stay cheap to change.', 'A wireframe shows where information and actions go, with little visual detail. It lets you discuss structure before color or imagery.', 'Write the path from start to result, then sketch only the screens that path needs. Include empty, loading, and error states.', 'Practice Wireframing Low-Fidelity Screens in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Sketch a wireframe of a course list, including the state when nothing matches. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Wireframing Low-Fidelity Screens, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Choosing a course can be a list, a detail page, and a confirmation. A search with no results needs guidance, not a blank page.', 'Sketch a wireframe of a course list, including the state when nothing matches.', 'Include heading, search, and rows with name and price. When nothing matches, show the query and a way to clear the filter.'),
('UX/UI Design Beginner', 'Information Architecture and Flows', 'Empty, Loading, and Error States', 3, 4, 'Empty, Loading, and Error States', 'Design the often-missed states that make products feel reliable.', 'Empty, loading, and error states are part of the experience. They tell people what is happening and what to do next.', 'Write the message, the reason if known, and one clear next action. Do not leave a blank frame while data loads.', 'Practice Empty, Loading, and Error States in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write copy for loading and failed load of a lesson reading. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Empty, Loading, and Error States, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Wishlist empty: You have not saved a course yet, with a button to browse the catalog.', 'Write copy for loading and failed load of a lesson reading.', 'Loading: Opening the lesson… Error: We could not load this reading. Try again. Keep the lesson title visible so people know where they are.'),
('UX/UI Design Beginner', 'Visual UI Design', 'Typography for Interfaces', 4, 1, 'Typography for Interfaces', 'Choose type scales, hierarchy, and readable line lengths for screens.', 'Type hierarchy tells someone what to read first. Size, weight, and spacing should support the role of each text block. Not every line should compete.', 'Define styles for headings, body, and labels. Check line length on desktop and mobile. Prefer a small, consistent scale over many one-off sizes.', 'Practice Typography for Interfaces in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: A card currently uses the same text size for everything. Name three type changes. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Typography for Interfaces, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A course card can use the name as the strong heading and the description as secondary text.', 'A card currently uses the same text size for everything. Name three type changes.', 'Give the course name more weight, reduce secondary details, and keep body text at a readable size. Check that it still fits on a small screen.'),
('UX/UI Design Beginner', 'Visual UI Design', 'Color, Contrast, and Theme', 4, 2, 'Color, Contrast, and Theme', 'Build a simple palette with semantic colors for success, warning, and error.', 'Color supports meaning and brand, but contrast must keep text readable. Semantic colors for success, warning, and error should stay consistent across screens.', 'Pair color with text or an icon. Test light text on the real background. Limit the palette so status colors stay recognizable.', 'Practice Color, Contrast, and Theme in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Propose a minimal palette: background, text, primary action, and error. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Color, Contrast, and Theme, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Error red on a button label needs enough contrast, and the message should also say what failed.', 'Propose a minimal palette: background, text, primary action, and error.', 'Neutral background and text, one primary action color, and one error color used with a text message. Avoid using error red for decoration.'),
('UX/UI Design Beginner', 'Visual UI Design', 'Spacing, Layout, and Grids', 4, 3, 'Spacing, Layout, and Grids', 'Use consistent spacing tokens and grids to keep screens calm.', 'Spacing creates groups. Related items sit closer; sections sit farther apart. A simple spacing scale beats random gaps.', 'Align to a grid or an 8px rhythm. Check margins at the screen edge and between cards.', 'Practice Spacing, Layout, and Grids in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Explain how you would use an 8px spacing system on a settings page. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Spacing, Layout, and Grids, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A settings page with 16px between rows and 32px between sections reads calmer than uneven gaps.', 'Explain how you would use an 8px spacing system on a settings page.', '8 for tight related labels, 16 between rows, 24–32 between sections. Keep left alignment consistent across rows.'),
('UX/UI Design Beginner', 'Visual UI Design', 'Components and Design Systems Intro', 4, 4, 'Components and Design Systems Intro', 'Create reusable buttons, inputs, and cards so designs stay consistent.', 'Components are reusable UI pieces with defined states. A lightweight design system starts with a few building blocks used everywhere.', 'Define default, hover, disabled, and error for controls you reuse. Document spacing and label rules once.', 'Practice Components and Design Systems Intro in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: List the first five components you would put in a beginner UI kit. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Components and Design Systems Intro, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A primary button component used on enroll and save prevents each screen inventing a new style.', 'List the first five components you would put in a beginner UI kit.', 'Primary button, secondary button, text input, course card, and empty state. Add focus and disabled states for the buttons and input.'),
('UX/UI Design Beginner', 'Visual UI Design', 'Mobile and Responsive Considerations', 4, 5, 'Mobile and Responsive Considerations', 'Adapt layouts for small screens without losing hierarchy or tap targets.', 'Small screens need clearer priority and larger tap targets. Responsive design reflows layout; it should not merely shrink everything.', 'Stack columns, keep primary actions reachable, and test with a thumb in mind. Hide or relocate secondary detail instead of crowding.', 'Practice Mobile and Responsive Considerations in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Name three mobile checks for a course detail screen. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Mobile and Responsive Considerations, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A three-column desktop catalog may become a single scrolling list on mobile with the same card hierarchy.', 'Name three mobile checks for a course detail screen.', 'Title readable without zoom, enroll button reachable, and related links not competing with the primary action.'),
('UX/UI Design Beginner', 'Prototyping and Handoff', 'Interactive Prototypes in Figma', 5, 1, 'Interactive Prototypes in Figma', 'Connect frames into a clickable prototype for demos and testing.', 'An interactive prototype simulates clicks and state changes so you can test a path. It does not need a real database, but it must respond at the points your question depends on.', 'Set the start, the goal, and the path you support. Include a way back. Tell participants what the prototype cannot do without naming which control to press.', 'Practice Interactive Prototypes in Figma in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Describe the states and screen changes for saving a course to a wishlist. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Interactive Prototypes in Figma, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'If the test is choose a course, open detail, and enroll, keep the same course name visible along the path.', 'Describe the states and screen changes for saving a course to a wishlist.', 'Not saved, then saved after the click, then the saved list shows that course. Pressing again should unsaved it consistently.'),
('UX/UI Design Beginner', 'Prototyping and Handoff', 'Usability Testing Basics', 5, 2, 'Usability Testing Basics', 'Run a lightweight test script and capture observations instead of opinions.', 'A usability test asks a person to try a task while you watch. State the goal without naming the button so you can see whether they understand it themselves.', 'Note success, hesitation, and mistakes. Ask why after the moment, without blaming them. Order problems by impact and frequency.', 'Practice Usability Testing Basics in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write one test task and three note columns for a course search page. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Usability Testing Basics, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Find a design course for someone with no background and check the price is a better task than click the Beginner filter.', 'Write one test task and three note columns for a course search page.', 'Task: find a beginner design course within a budget. Columns: succeeded, observed behavior, and what they said. Keep your suggestions out of the evidence column.'),
('UX/UI Design Beginner', 'Prototyping and Handoff', 'Turning Feedback into Iterations', 5, 3, 'Turning Feedback into Iterations', 'Prioritize issues by severity and update the design without rewriting everything.', 'Feedback becomes useful when you turn it into ordered changes. Fix blockers on the main task first. Taste comments come after task success.', 'Write expected versus actual, choose the change, and retest with a comparable task. Keep an iteration log.', 'Practice Turning Feedback into Iterations in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Summarize two usability findings and the change you would make for each. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Turning Feedback into Iterations, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'If people say the page looks nice but cannot find Start, fix information order before adding decoration.', 'Summarize two usability findings and the change you would make for each.', 'Cannot find Start: raise the primary action. Price surprises at the last step: show price earlier on detail. Retest both.'),
('UX/UI Design Beginner', 'Prototyping and Handoff', 'Developer Handoff Checklist', 5, 4, 'Developer Handoff Checklist', 'Prepare specs, assets, and edge cases so engineering can implement accurately.', 'Handoff is a communication package: flows, component states, spacing, assets, and edge cases. Engineers should not have to guess empty or error behavior.', 'Link the prototype, note measurements or tokens, and list what is out of scope. Walk through the main path together once.', 'Practice Developer Handoff Checklist in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a four-item handoff checklist for a course card. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Developer Handoff Checklist, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'Include the wishlist empty state and the failed-save message in the handoff, not only the happy path.', 'Write a four-item handoff checklist for a course card.', 'All card states, spacing tokens, accessible name for the action, and behavior when the image is missing.'),
('UX/UI Design Beginner', 'Course Summary', 'Key Takeaways for New Designers', 6, 1, 'Key Takeaways for New Designers', 'Recap research, flows, UI craft, and testing as one continuous loop.', 'Good beginner practice connects understanding users, structuring flows, crafting UI, prototyping, and testing. Screens alone are not the whole craft.', 'Keep a personal loop: evidence → problem → flow → interface → test → revise.', 'Practice Key Takeaways for New Designers in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: List the loop steps you will use on your next design task. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Key Takeaways for New Designers, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A first case study can show a journey map, three wireframes, a UI iteration, and a usability note.', 'List the loop steps you will use on your next design task.', 'Gather evidence, write the problem, draw the flow, design UI states, test with one user, and revise the blocker first.'),
('UX/UI Design Beginner', 'Course Summary', 'Building a Beginner Design Portfolio', 6, 2, 'Building a Beginner Design Portfolio', 'Present process, not just final screenshots, in a first case study.', 'A beginner portfolio should show how you think: problem, research, decisions, iterations, and outcome. Final screens without process are hard to trust.', 'Pick one case with a clear user goal. Show before/after or iteration notes. Be honest about limits and what you would do next.', 'Practice Building a Beginner Design Portfolio in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Outline one case study section list you would include in your portfolio. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', 'While you study Building a Beginner Design Portfolio, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', 'A signup redesign case can include the old pain point, a flow, two iterations, and a test result from three people.', 'Outline one case study section list you would include in your portfolio.', 'Context and goal, research insights, flow and wireframes, UI iterations, test findings, and next steps. Keep each section short and visual.');

-- Rebuild curriculum rows for the expanded courses (cascades sub_lessons,
-- assignments, and progress).
DELETE FROM courseflow.course_lessons AS lesson
USING courseflow.courses AS course
WHERE lesson.course_id = course.id
  AND course.name IN ('Software Developer', 'UX/UI Design Beginner');

INSERT INTO courseflow.course_lessons (course_id, name, position, sub_lessons)
SELECT course.id, demo.lesson_name, demo.lesson_order, COUNT(*)::INT
FROM courseflow.demo_lesson_content AS demo
JOIN courseflow.courses AS course ON course.name = demo.course_title
WHERE demo.course_title IN ('Software Developer', 'UX/UI Design Beginner')
GROUP BY course.id, demo.lesson_name, demo.lesson_order
ORDER BY course.id, demo.lesson_order;

INSERT INTO courseflow.sub_lessons (lesson_id, name, position)
SELECT lesson.id, demo.sub_lesson_name, demo.sub_lesson_order
FROM courseflow.demo_lesson_content AS demo
JOIN courseflow.courses AS course ON course.name = demo.course_title
JOIN courseflow.course_lessons AS lesson
  ON lesson.course_id = course.id
 AND lesson.position = demo.lesson_order
WHERE demo.course_title IN ('Software Developer', 'UX/UI Design Beginner')
ORDER BY course.id, demo.lesson_order, demo.sub_lesson_order;
